\documentclass{article}
% A1 portrait: 594mm × 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{microtype}
\pagestyle{empty}

% ── Dark-mode developer palette ──────────────────────────────────
\definecolor{primary}{HTML}{0F1729}      % deep navy (title bar, backgrounds)
\definecolor{secondary}{HTML}{1E3A5F}    % dark blue (card accents)
\definecolor{accent}{HTML}{2563EB}       % electric blue (highlights)
\definecolor{amber}{HTML}{F59E0B}        % amber (TypeScript / warning)
\definecolor{mint}{HTML}{10B981}         % mint green (Python)
\definecolor{jsyellow}{HTML}{EAB308}     % JavaScript yellow
\definecolor{bgposter}{HTML}{0D1117}     % near-black background
\definecolor{cardbg}{HTML}{161B27}       % card background
\definecolor{cardbg2}{HTML}{1A2235}      % alternate card
\definecolor{cardbg3}{HTML}{141E30}      % third card tone
\definecolor{textlight}{HTML}{E2E8F0}    % primary text (light)
\definecolor{textmid}{HTML}{94A3B8}      % secondary text
\definecolor{textfaint}{HTML}{475569}    % muted text
\definecolor{rust}{HTML}{F97316}         % Rust orange
\definecolor{postgres}{HTML}{336791}     % PostgreSQL blue
\definecolor{aws}{HTML}{FF9900}          % AWS orange
\definecolor{statbg}{HTML}{1E2D45}       % stat banner bg
\definecolor{linecolor}{HTML}{2D3748}    % grid lines

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──────────────────────────────────────────────────
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=0pt, topsep=2pt,
  label={\color{accent}$\bullet$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=4pt, parsep=0pt, topsep=2pt,
  label={\color{accent}\bfseries\arabic*.}}

% ── Card styles (dark-mode left-stripe) ───────────────────────────
\tcbset{
  navycard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{accent},
    left=12pt, right=10pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg,
    toptitle=5pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={accent!30},
    valign=top, frame hidden,
  },
  ambercard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg2,
    borderline west={4pt}{0pt}{amber},
    left=12pt, right=10pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=cardbg2,
    toptitle=5pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={amber!30},
    valign=top, frame hidden,
  },
  mintcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg3,
    borderline west={4pt}{0pt}{mint},
    left=12pt, right=10pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{mint},
    coltitle=mint, colbacktitle=cardbg3,
    toptitle=5pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={mint!30},
    valign=top, frame hidden,
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{amber},
    left=12pt, right=10pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=secondary,
    toptitle=5pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={amber!40},
    valign=top, frame hidden,
  },
}

% ── Inline highlight boxes ────────────────────────────────────────
\newcommand{\infobox}[3]{%
  \vspace{3pt}%
  \fcolorbox{#1!40}{#1!15}{\parbox{0.9\linewidth}{%
    \fontsize{17}{22}\selectfont\color{textlight} #3%
  }}\vspace{3pt}%
}

% ── Stat pill ─────────────────────────────────────────────────────
\newcommand{\statpill}[3]{%
  \begin{minipage}[t]{#1\linewidth}\centering
    {\fontsize{42}{50}\selectfont\bfseries\color{#2} #3}%
  \end{minipage}%
}

% ── Language bar (mini horizontal bar) ───────────────────────────
\newcommand{\langbar}[3]{%
  % #1=language  #2=color  #3=width fraction of 0.9\linewidth
  \noindent
  {\fontsize{16}{20}\selectfont\color{textmid} #1}\hfill
  {\fontsize{16}{20}\selectfont\color{#2}\bfseries}%
  \newline
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=24, spacing=2mm},
]

%────────────────────────────────────────────────────────────────────
% TITLE BAR
%────────────────────────────────────────────────────────────────────
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=18pt, right=18pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{13}{16}\selectfont\bfseries\color{textfaint}\MakeUppercase{JetBrains State of Developer Ecosystem 2024}}\\[4pt]
  {\fontsize{38}{46}\selectfont\bfseries\color{textlight}Language Wars \&}\\[-2pt]
  {\fontsize{38}{46}\selectfont\bfseries\color{accent}Rising Stars}\\[6pt]
  {\fontsize{14}{18}\selectfont\color{textmid}
    A data-forward map of programming languages, databases \&\ cloud platforms heading into 2025}\\[4pt]
  {\fontsize{12}{16}\selectfont\color{textfaint}$\bullet$~23,262 developers worldwide~$\bullet$~jetbrains.com/lp/devecosystem-2024}
}

%────────────────────────────────────────────────────────────────────
% STAT BANNER — 4 headline numbers
%────────────────────────────────────────────────────────────────────
\posterbox[
  enhanced, colback=statbg, colframe=statbg,
  arc=0pt, boxrule=0pt,
  borderline south={2pt}{0pt}{accent!30},
  left=8pt, right=8pt, top=6pt, bottom=6pt,
  halign=center, valign=center,
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{44}{52}\selectfont\bfseries\color{jsyellow} 61\%}\\[1pt]
    {\fontsize{13}{16}\selectfont\color{textmid} JavaScript\\(plateau)}
  \end{minipage}\hfill\vrule width 0.5pt height 42pt depth 8pt\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{44}{52}\selectfont\bfseries\color{mint} 57\%}\\[1pt]
    {\fontsize{13}{16}\selectfont\color{textmid} Python\\(closing in)}
  \end{minipage}\hfill\vrule width 0.5pt height 42pt depth 8pt\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{44}{52}\selectfont\bfseries\color{amber} 37\%}\\[1pt]
    {\fontsize{13}{16}\selectfont\color{textmid} TypeScript\\(12\%$\to$37\%)}
  \end{minipage}\hfill\vrule width 0.5pt height 42pt depth 8pt\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{44}{52}\selectfont\bfseries\color{accent} 18\%}\\[1pt]
    {\fontsize{13}{16}\selectfont\color{textmid} Devs building\\AI integrations}
  \end{minipage}
}

%────────────────────────────────────────────────────────────────────
% COLUMN 1 — Language Trajectories (main story)
%────────────────────────────────────────────────────────────────────

% 8-Year Language Usage Chart (centerpiece)
\posterbox[navycard, title={Top Languages: 8-Year Trajectory (2017--2024)}
]{name=langtable, column=1, between=row5 and row12}{
  \fontsize{16}{21}\selectfont\color{textlight}
  \renewcommand{\arraystretch}{1.55}
  \begin{tabular}{@{}l r r r r r@{}}
    \rowcolor{accent!20}
    \textbf{Language} & \textbf{2017} & \textbf{2019} & \textbf{2021} & \textbf{2023} & \textbf{2024}\\
    \hline
    \rowcolor{cardbg}
    {\color{jsyellow}\textbf{JavaScript}} & 65\% & 69\% & 69\% & 61\% & \textbf{61\%}\\
    \rowcolor{cardbg2}
    {\color{mint}\textbf{Python}} & 32\% & 49\% & 52\% & 54\% & \textbf{57\%}\\
    \rowcolor{cardbg}
    {\color{textmid}HTML/CSS} & 60\% & 61\% & 60\% & 52\% & 51\%\\
    \rowcolor{cardbg2}
    {\color{textmid}SQL} & 42\% & 56\% & 54\% & 52\% & 48\%\\
    \rowcolor{cardbg}
    {\color{textmid}Java} & 47\% & 50\% & 49\% & 49\% & 46\%\\
    \rowcolor{cardbg2}
    {\color{amber}\textbf{TypeScript}} & 12\% & 25\% & 29\% & 34\% & \textbf{37\%}\\
    \rowcolor{cardbg}
    {\color{rust}\textbf{Rust}} & --- & 6\% & 8\% & 7\% & \textbf{8\%}\\
    \rowcolor{cardbg2}
    {\color{textmid}Go} & 17\% & 20\% & 23\% & 18\% & 17\%\\
  \end{tabular}

  \vspace{6pt}
  \infobox{accent}{}{%
    {\color{accent}\bfseries Key shift:} Python (32\%$\to$57\%) gained 25 points over 8 years.
    JavaScript's share peaked at 69\% in 2019 and has since contracted to 61\%.%
  }
  \vspace{3pt}
  \infobox{mint}{}{%
    {\color{mint}\bfseries TypeScript surge:} 12\%$\to$37\% in 7 years---the steepest growth
    trajectory of any major language. JS and TS coexist rather than compete.%
  }
}

% Visual percentage bars
\posterbox[ambercard, title={Usage Share Visualised (2024)}
]{name=bars, column=1, between=row12 and row17}{
  \fontsize{15}{20}\selectfont

  \newcommand{\pbar}[3]{%
    \noindent
    \makebox[62pt][l]{{\color{##2}\bfseries ##1}}%
    \textcolor{##2}{\rule{##3}{8pt}}\\[3pt]%
  }

  \pbar{JS\ 61\%}{jsyellow}{0.61\linewidth}
  \pbar{Python\ 57\%}{mint}{0.57\linewidth}
  \pbar{HTML/CSS\ 51\%}{textmid}{0.51\linewidth}
  \pbar{SQL\ 48\%}{textmid}{0.48\linewidth}
  \pbar{Java\ 46\%}{textmid}{0.46\linewidth}
  \pbar{TS\ 37\%}{amber}{0.37\linewidth}
  \pbar{Rust\ 8\%}{rust}{0.08\linewidth}

  \vspace{5pt}
  \infobox{amber}{}{%
    {\color{amber}\bfseries Python's trajectory:} Started at 32\% in 2017 (near PHP's 30\%).
    Now used by $>$half of all developers globally.%
  }
}

% Databases
\posterbox[mintcard, title={Databases: PostgreSQL's Surge}
]{name=databases, column=1, between=row17 and row21}{
  \fontsize{16}{21}\selectfont\color{textlight}
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{}l r r r@{}}
    \rowcolor{accent!20}
    \textbf{Database} & \textbf{2019} & \textbf{2022} & \textbf{2024}\\
    \hline
    \rowcolor{cardbg}
    {\color{textmid}MySQL} & 60\% & 52\% & 52\%\\
    \rowcolor{cardbg2}
    {\color{postgres}\textbf{PostgreSQL}} & 32\% & 38\% & \textbf{45\%}\\
    \rowcolor{cardbg}
    {\color{textmid}MongoDB} & 30\% & 27\% & 30\%\\
    \rowcolor{cardbg2}
    {\color{textmid}SQLite} & 29\% & 27\% & 30\%\\
    \rowcolor{cardbg}
    {\color{textmid}Redis} & 22\% & 18\% & 20\%\\
  \end{tabular}
  \vspace{5pt}

  \infobox{postgres}{}{%
    {\color{postgres}\bfseries PostgreSQL} up 13 points since 2019; closing the gap with MySQL.
    Open-source databases now dominate the stack.%
  }
}

% Cloud platforms
\posterbox[navycard, title={Cloud Platforms (2024)}
]{name=cloud, column=1, between=row21 and row24}{
  \fontsize{16}{21}\selectfont

  \noindent
  \makebox[62pt][l]{{\color{aws}\bfseries AWS\ 46\%}}\textcolor{aws}{\rule{0.46\linewidth}{8pt}}\\[3pt]
  \makebox[62pt][l]{{\color{accent}\bfseries Azure\ 17\%}}\textcolor{accent}{\rule{0.17\linewidth}{8pt}}\\[3pt]
  \makebox[62pt][l]{{\color{mint}\bfseries GCP\ 11\%}}\textcolor{mint}{\rule{0.11\linewidth}{8pt}}\\[5pt]

  \infobox{aws}{}{%
    AWS leads at 46\% (down from 51\% in 2022). Azure \& GCP gaining ground.%
  }
}

%────────────────────────────────────────────────────────────────────
% COLUMN 2 — Promise Index + Context
%────────────────────────────────────────────────────────────────────

% Promise Index (key callout section)
\posterbox[highlightcard, title={Language Promise Index\textsuperscript{\textnormal{\fontsize{11}{13}\selectfont TM}}: Where the Ecosystem Is Heading}
]{name=promise, column=2, between=row5 and row11}{
  \fontsize{15}{19}\selectfont\color{textlight}
  {\fontsize{13}{16}\selectfont\color{textmid}
    Composite score: 5-year growth $+$ stability $+$ intent-to-adopt $+$ retention}
  \vspace{6pt}

  \renewcommand{\arraystretch}{1.6}
  \begin{tabular}{@{}r l r@{}}
    \rowcolor{accent!20}
    \textbf{\#} & \textbf{Language} & \textbf{Score}\\
    \hline
    \rowcolor{cardbg}
    1 & {\color{amber}\bfseries TypeScript} & \textbf{199}\\
    \rowcolor{cardbg2}
    2 & {\color{rust}\bfseries Rust} & \textbf{198}\\
    \rowcolor{cardbg}
    3 & {\color{mint}\bfseries Python} & 151\\
    \rowcolor{cardbg2}
    4 & {\color{textlight}Go} & 129\\
    \rowcolor{cardbg}
    5 & {\color{textmid}Lua} & 118\\
    \rowcolor{cardbg2}
    6 & {\color{textmid}C++} & 113\\
    \rowcolor{cardbg}
    7 & {\color{textmid}Kotlin} & 113\\
  \end{tabular}

  \vspace{7pt}
  % TypeScript hero callout
  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=1pt, colframe=amber,
    colback=amber!10, left=8pt, right=8pt, top=5pt, bottom=5pt]
    \centering
    {\fontsize{52}{60}\selectfont\bfseries\color{amber} 199}\\[-2pt]
    {\fontsize{14}{17}\selectfont\color{textlight}\bfseries TypeScript Promise Index}\\[2pt]
    {\fontsize{13}{16}\selectfont\color{textmid} Highest score of any language --- signals\\where the ecosystem is heading in 2025+}
  \end{tcolorbox}

  \vspace{4pt}
  \infobox{rust}{}{%
    {\color{rust}\bfseries Rust \& Go:} Most-planned-to-adopt languages.
    1-in-6 Go developers considering a switch to Rust.%
  }
}

% TypeScript vs JavaScript narrative
\posterbox[ambercard, title={TypeScript: The Breakout Story}
]{name=tsnarrative, column=2, between=row11 and row15}{
  \fontsize{16}{21}\selectfont

  \begin{center}
    \begin{minipage}[t]{0.44\linewidth}\centering
      {\fontsize{11}{13}\selectfont\color{textmid} 2017}\\
      {\fontsize{36}{42}\selectfont\bfseries\color{amber} 12\%}\\
      {\fontsize{11}{14}\selectfont\color{textmid} TypeScript usage}
    \end{minipage}
    \hfill
    {\fontsize{28}{34}\selectfont\color{accent}$\longrightarrow$}
    \hfill
    \begin{minipage}[t]{0.44\linewidth}\centering
      {\fontsize{11}{13}\selectfont\color{textmid} 2024}\\
      {\fontsize{36}{42}\selectfont\bfseries\color{amber} 37\%}\\
      {\fontsize{11}{14}\selectfont\color{textmid} TypeScript usage}
    \end{minipage}
  \end{center}

  \vspace{6pt}
  \infobox{amber}{}{%
    {\color{amber}\bfseries $+$25 pts in 7 years} --- steepest growth of any major language.
    TypeScript's Promise Index of 199 signals this is not slowing down.%
  }
  \vspace{3pt}
  \infobox{accent}{}{%
    TypeScript \& JavaScript complement each other---TS adoption did not cannibalize JS usage.%
  }
}

% Platforms / Where code runs
\posterbox[mintcard, title={Where Applications Live (2024)}
]{name=platforms, column=2, between=row15 and row19}{
  \fontsize{16}{21}\selectfont

  \noindent
  \makebox[82pt][l]{{\color{accent}\bfseries Browser\ 58\%}}\textcolor{accent}{\rule{0.46\linewidth}{8pt}}\\[4pt]
  \makebox[82pt][l]{{\color{mint}\bfseries Desktop\ 53\%}}\textcolor{mint}{\rule{0.42\linewidth}{8pt}}\\[4pt]
  \makebox[82pt][l]{{\color{accent}\bfseries Srv/Cloud\ 56\%}}\textcolor{accent!60}{\rule{0.45\linewidth}{8pt}}\\[4pt]
  \makebox[82pt][l]{{\color{textmid}\bfseries Mobile\ 30\%}}\textcolor{textmid}{\rule{0.24\linewidth}{8pt}}\\

  \vspace{5pt}
  \infobox{mint}{}{%
    {\color{mint}\bfseries Surprise:} Desktop (53\%) surpasses Mobile (30\%). Mobile-first
    assumptions underestimate where production software actually runs.%
  }
}

% AI integration section
\posterbox[highlightcard, title={AI in the Developer Workflow}
]{name=ai, column=2, between=row19 and row22}{
  \fontsize{16}{21}\selectfont

  \begin{center}
    {\fontsize{52}{60}\selectfont\bfseries\color{accent} 18\%}\\[-2pt]
    {\fontsize{14}{17}\selectfont\color{textlight} of developers building AI integrations}
  \end{center}

  \vspace{4pt}
  \infobox{mint}{}{%
    {\color{mint}\bfseries Python dominates AI/ML:} 31\% of Python developers do AI work.%
  }
  \vspace{2pt}
  \infobox{rust}{}{%
    {\color{rust}\bfseries C++ surprise:} 11\% of C++ devs report AI/ML involvement.%
  }
  \vspace{2pt}
  \infobox{accent}{}{%
    {\color{accent}\bfseries Docker:} 49\% use it locally. Containerization is now standard.%
  }
}

% Key Takeaways
\posterbox[navycard, title={Key Takeaways for 2025}
]{name=takeaways, column=2, between=row22 and row24}{
  \fontsize{15}{20}\selectfont
  \begin{enumerate}[itemsep=5pt]
    \item {\color{amber}\bfseries TypeScript} (Promise Index 199) is the ecosystem's clearest momentum signal.
    \item {\color{mint}\bfseries Python} is closing in on JavaScript --- the 2025 gap could be $<$3 points.
    \item {\color{postgres}\bfseries PostgreSQL} is the rising database leader; open-source dominates.
    \item {\color{accent}\bfseries AWS} leads cloud but faces steady erosion from Azure \& GCP.
    \item {\color{accent}\bfseries AI integration} at 18\% signals production AI is no longer niche.
  \end{enumerate}
}

