\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{microtype}
\pagestyle{empty}

% ── Dark-mode developer palette ─────────────────────────────────
\definecolor{primary}{HTML}{0F1729}
\definecolor{secondary}{HTML}{1E3A5F}
\definecolor{accent}{HTML}{2563EB}
\definecolor{amber}{HTML}{F59E0B}
\definecolor{mint}{HTML}{10B981}
\definecolor{jsyellow}{HTML}{EAB308}
\definecolor{bgposter}{HTML}{0D1117}
\definecolor{cardbg}{HTML}{161B27}
\definecolor{cardbg2}{HTML}{1A2235}
\definecolor{cardbg3}{HTML}{141E30}
\definecolor{textlight}{HTML}{E2E8F0}
\definecolor{textmid}{HTML}{94A3B8}
\definecolor{textfaint}{HTML}{475569}
\definecolor{rust}{HTML}{F97316}
\definecolor{postgres}{HTML}{336791}
\definecolor{aws}{HTML}{FF9900}
\definecolor{statbg}{HTML}{1E2D45}

\pagecolor{bgposter}
\color{textlight}

% ── List styling ─────────────────────────────────────────────────
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=0pt, topsep=2pt,
  label={\color{accent}$\bullet$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=5pt, parsep=0pt, topsep=2pt,
  label={\color{accent}\bfseries\arabic*.}}

% ── Card styles ───────────────────────────────────────────────────
\tcbset{
  navycard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{accent},
    left=12pt, right=10pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg,
    toptitle=5pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={accent!30},
    valign=top, frame hidden,
  },
  ambercard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg2,
    borderline west={4pt}{0pt}{amber},
    left=12pt, right=10pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=cardbg2,
    toptitle=5pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={amber!30},
    valign=top, frame hidden,
  },
  mintcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg3,
    borderline west={4pt}{0pt}{mint},
    left=12pt, right=10pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{mint},
    coltitle=mint, colbacktitle=cardbg3,
    toptitle=5pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={mint!30},
    valign=top, frame hidden,
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{amber},
    left=12pt, right=10pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=secondary,
    toptitle=5pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={amber!40},
    valign=top, frame hidden,
  },
}

% ── Helpers ───────────────────────────────────────────────────────
% \ibox{bordercolor}{bgcolor}{text}
\newcommand{\ibox}[3]{%
  \vspace{3pt}%
  \fcolorbox{#1!50}{#1!12}{\parbox{0.88\linewidth}{%
    \fontsize{17}{22}\selectfont\color{textlight} #3%
  }}\vspace{3pt}%
}

% horizontal rule bar: \hbar{color}{fraction of \linewidth}{label}{pct}
\newcommand{\hbar}[4]{%
  \noindent
  \makebox[90pt][l]{{\fontsize{16}{20}\selectfont\color{#1}\bfseries #3}}%
  \textcolor{#1}{\rule{#2\linewidth}{7pt}}%
  \hspace{4pt}{\fontsize{14}{18}\selectfont\color{textmid}#4}\\[4pt]%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=24, spacing=2mm},
]

%──────────────────────────────────────────────────────────────────
% TITLE BAR
%──────────────────────────────────────────────────────────────────
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=18pt, right=18pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{13}{16}\selectfont\bfseries\color{textfaint}%
    JETBRAINS STATE OF DEVELOPER ECOSYSTEM 2024}\\[6pt]
  {\fontsize{42}{50}\selectfont\bfseries\color{textlight}Language Wars \&\ }%
  {\fontsize{42}{50}\selectfont\bfseries\color{accent}Rising Stars}\\[6pt]
  {\fontsize{15}{19}\selectfont\color{textmid}%
    A data-forward map of programming languages, databases \&\ cloud
    platforms heading into 2025}\\[5pt]
  {\fontsize{13}{16}\selectfont\color{textfaint}%
    $\bullet$\ 23{,}262 developers worldwide
    $\quad\bullet\quad$ jetbrains.com/lp/devecosystem-2024}
}

%──────────────────────────────────────────────────────────────────
% STAT BANNER
%──────────────────────────────────────────────────────────────────
\posterbox[
  enhanced, colback=statbg, colframe=statbg,
  arc=0pt, boxrule=0pt,
  borderline south={2pt}{0pt}{accent!30},
  left=8pt, right=8pt, top=7pt, bottom=7pt,
  halign=center, valign=center,
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{46}{54}\selectfont\bfseries\color{jsyellow} 61\%}\\[1pt]
    {\fontsize{13}{16}\selectfont\color{textmid}JavaScript\\(plateau since 2021)}
  \end{minipage}\hfill
  \textcolor{textfaint}{\vrule height 44pt depth 10pt width 0.5pt}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{46}{54}\selectfont\bfseries\color{mint} 57\%}\\[1pt]
    {\fontsize{13}{16}\selectfont\color{textmid}Python\\(up from 32\% in 2017)}
  \end{minipage}\hfill
  \textcolor{textfaint}{\vrule height 44pt depth 10pt width 0.5pt}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{46}{54}\selectfont\bfseries\color{amber} 37\%}\\[1pt]
    {\fontsize{13}{16}\selectfont\color{textmid}TypeScript\\(was 12\% in 2017)}
  \end{minipage}\hfill
  \textcolor{textfaint}{\vrule height 44pt depth 10pt width 0.5pt}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    {\fontsize{46}{54}\selectfont\bfseries\color{accent} 18\%}\\[1pt]
    {\fontsize{13}{16}\selectfont\color{textmid}Devs building\\AI integrations}
  \end{minipage}
}

%──────────────────────────────────────────────────────────────────
% COL 1 – Language data (main story)
%──────────────────────────────────────────────────────────────────

\posterbox[navycard, title={Top Languages: 8-Year Trajectory (2017--2024)}
]{name=langtable, column=1, between=row5 and row12}{
  \fontsize{16}{21}\selectfont\color{textlight}
  \renewcommand{\arraystretch}{1.6}
  \begin{tabular}{@{}l@{\hspace{6pt}} r@{\hspace{8pt}} r@{\hspace{8pt}} r@{\hspace{8pt}} r@{\hspace{8pt}} r@{}}
    \rowcolor{accent!18}
    \textbf{Language} & \textbf{2017} & \textbf{2019} & \textbf{2021} & \textbf{2023} & \textbf{2024}\\
    \hline
    \rowcolor{cardbg}
    {\color{jsyellow}\bfseries JavaScript} & 65\% & 69\% & 69\% & 61\% & \bfseries 61\%\\
    \rowcolor{cardbg2}
    {\color{mint}\bfseries Python}         & 32\% & 49\% & 52\% & 54\% & \bfseries 57\%\\
    \rowcolor{cardbg}
    {\color{textmid}HTML/CSS}              & 60\% & 61\% & 60\% & 52\% & 51\%\\
    \rowcolor{cardbg2}
    {\color{textmid}SQL}                   & 42\% & 56\% & 54\% & 52\% & 48\%\\
    \rowcolor{cardbg}
    {\color{textmid}Java}                  & 47\% & 50\% & 49\% & 49\% & 46\%\\
    \rowcolor{cardbg2}
    {\color{amber}\bfseries TypeScript}    & 12\% & 25\% & 29\% & 34\% & \bfseries 37\%\\
    \rowcolor{cardbg}
    {\color{rust}\bfseries Rust}           & ---  & 6\%  & 8\%  & 7\%  & \bfseries 8\%\\
    \rowcolor{cardbg2}
    {\color{textmid}Go}                    & 17\% & 20\% & 23\% & 18\% & 17\%\\
  \end{tabular}
  \vspace{6pt}

  \ibox{accent}{}{%
    {\color{accent}\bfseries Key shift:} Python grew 25 pts (32$\to$57\%) over 8 years.
    JavaScript peaked at 69\% in 2019, now plateaued at 61\%.%
  }
  \vspace{2pt}
  \ibox{mint}{}{%
    {\color{mint}\bfseries TypeScript surge:} 12\%$\to$37\% in 7 years ---
    steepest growth of any major language. JS \& TS coexist rather than compete.%
  }
}

\posterbox[ambercard, title={2024 Usage Share}
]{name=bars, column=1, between=row12 and row17}{
  \fontsize{16}{20}\selectfont

  \hbar{jsyellow}{0.585}{JS\ 61\%}{}
  \hbar{mint}{0.545}{Python\ 57\%}{}
  \hbar{textmid}{0.488}{HTML/CSS\ 51\%}{}
  \hbar{textmid}{0.459}{SQL\ 48\%}{}
  \hbar{textmid}{0.440}{Java\ 46\%}{}
  \hbar{amber}{0.354}{TypeScript\ 37\%}{}
  \hbar{rust}{0.077}{Rust\ 8\%}{}

  \vspace{4pt}
  \ibox{amber}{}{%
    {\color{amber}\bfseries Python's arc:} Started near PHP (32\% vs 30\%) in 2017.
    Now used by $>$half of all developers globally.%
  }
}

\posterbox[mintcard, title={Databases: PostgreSQL's Surge}
]{name=databases, column=1, between=row17 and row21}{
  \fontsize{16}{21}\selectfont\color{textlight}
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{}l r r r@{}}
    \rowcolor{accent!18}
    \textbf{Database} & \textbf{2019} & \textbf{2022} & \textbf{2024}\\
    \hline
    \rowcolor{cardbg}
    {\color{textmid}MySQL}           & 60\% & 52\% & 52\%\\
    \rowcolor{cardbg2}
    {\color{postgres}\bfseries PostgreSQL} & 32\% & 38\% & \bfseries 45\%\\
    \rowcolor{cardbg}
    {\color{textmid}MongoDB}         & 30\% & 27\% & 30\%\\
    \rowcolor{cardbg2}
    {\color{textmid}SQLite}          & 29\% & 27\% & 30\%\\
    \rowcolor{cardbg}
    {\color{textmid}Redis}           & 22\% & 18\% & 20\%\\
  \end{tabular}
  \vspace{5pt}

  \ibox{postgres}{}{%
    {\color{postgres}\bfseries PostgreSQL} up 13 pts since 2019; narrowing gap with MySQL.
    Open-source databases dominate.%
  }
}

\posterbox[navycard, title={Cloud Platforms (2024)}
]{name=cloud, column=1, between=row21 and row24}{
  \fontsize{16}{20}\selectfont

  \hbar{aws}{0.44}{AWS\ 46\%}{}
  \hbar{accent}{0.163}{Azure\ 17\%}{}
  \hbar{mint}{0.106}{GCP\ 11\%}{}

  \vspace{3pt}
  \ibox{aws}{}{%
    AWS leads at 46\% (down from 51\% in 2022). Azure \& GCP gaining ground steadily.%
  }
}

%──────────────────────────────────────────────────────────────────
% COL 2 – Promise Index + Context
%──────────────────────────────────────────────────────────────────

\posterbox[highlightcard, title={Language Promise Index: Where the Ecosystem Is Heading}
]{name=promise, column=2, between=row5 and row11}{
  \fontsize{15}{19}\selectfont\color{textlight}
  {\fontsize{13}{16}\selectfont\color{textmid}%
    Composite score: 5-year growth $+$ stability $+$ intent-to-adopt $+$ retention}
  \vspace{5pt}

  \renewcommand{\arraystretch}{1.6}
  \begin{tabular}{@{}r@{\hspace{8pt}} l r@{}}
    \rowcolor{accent!18}
    \textbf{\#} & \textbf{Language} & \textbf{Score}\\
    \hline
    \rowcolor{cardbg}
    1 & {\color{amber}\bfseries TypeScript} & \bfseries 199\\
    \rowcolor{cardbg2}
    2 & {\color{rust}\bfseries Rust}        & \bfseries 198\\
    \rowcolor{cardbg}
    3 & {\color{mint}\bfseries Python}      & 151\\
    \rowcolor{cardbg2}
    4 & {\color{textlight}Go}               & 129\\
    \rowcolor{cardbg}
    5 & {\color{textmid}Lua}                & 118\\
    \rowcolor{cardbg2}
    6 & {\color{textmid}C++}                & 113\\
    \rowcolor{cardbg}
    7 & {\color{textmid}Kotlin}             & 113\\
  \end{tabular}

  \vspace{7pt}
  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=1pt, colframe=amber,
    colback=amber!12, left=8pt, right=8pt, top=6pt, bottom=6pt]
    \centering
    {\fontsize{56}{64}\selectfont\bfseries\color{amber} 199}\\[-2pt]
    {\fontsize{15}{18}\selectfont\color{textlight}\bfseries TypeScript Promise Index}\\[2pt]
    {\fontsize{13}{16}\selectfont\color{textmid}Highest score of any language ---
    signals where the ecosystem heads in 2025+}
  \end{tcolorbox}

  \vspace{4pt}
  \ibox{rust}{}{%
    {\color{rust}\bfseries Rust \& Go:} Most-planned-to-adopt languages.
    1-in-6 Go developers considering a switch to Rust.%
  }
}

\posterbox[ambercard, title={TypeScript: The Breakout Story}
]{name=tsnarrative, column=2, between=row11 and row15}{
  \fontsize{16}{20}\selectfont

  \begin{center}
    \begin{minipage}[t]{0.42\linewidth}\centering
      {\fontsize{12}{14}\selectfont\color{textmid} 2017}\\
      {\fontsize{38}{44}\selectfont\bfseries\color{amber} 12\%}\\
      {\fontsize{12}{14}\selectfont\color{textmid} TypeScript usage}
    \end{minipage}
    \hfill
    {\fontsize{30}{36}\selectfont\color{accent} $\longrightarrow$}
    \hfill
    \begin{minipage}[t]{0.42\linewidth}\centering
      {\fontsize{12}{14}\selectfont\color{textmid} 2024}\\
      {\fontsize{38}{44}\selectfont\bfseries\color{amber} 37\%}\\
      {\fontsize{12}{14}\selectfont\color{textmid} TypeScript usage}
    \end{minipage}
  \end{center}

  \vspace{6pt}
  \ibox{amber}{}{%
    {\color{amber}\bfseries $+$25 pts in 7 years} --- steepest growth of any major language.
    Promise Index of 199 signals acceleration continues.%
  }
  \vspace{3pt}
  \ibox{accent}{}{%
    TypeScript \& JavaScript complement each other --- TS adoption did not
    cannibalize JS usage. Both grow in tandem.%
  }
}

\posterbox[mintcard, title={Where Applications Live (2024)}
]{name=platforms, column=2, between=row15 and row19}{
  \fontsize{16}{20}\selectfont

  \hbar{accent}{0.556}{Browser\ 58\%}{}
  \hbar{accent!70}{0.537}{Server/Cloud\ 56\%}{}
  \hbar{mint}{0.508}{Desktop\ 53\%}{}
  \hbar{textmid}{0.288}{Mobile\ 30\%}{}

  \vspace{5pt}
  \ibox{mint}{}{%
    {\color{mint}\bfseries Surprise:} Desktop (53\%) beats Mobile (30\%).
    Mobile-first assumptions underestimate production software reality.%
  }
  \vspace{2pt}
  \ibox{accent}{}{%
    {\color{accent}\bfseries Docker:} 49\% of developers use it locally.
    Containerisation is now a default workflow step.%
  }
}

\posterbox[highlightcard, title={AI in the Developer Workflow}
]{name=ai, column=2, between=row19 and row22}{
  \fontsize{16}{20}\selectfont

  \begin{center}
    {\fontsize{56}{64}\selectfont\bfseries\color{accent} 18\%}\\[-2pt]
    {\fontsize{15}{18}\selectfont\color{textlight}%
      of developers building AI integrations}
  \end{center}

  \vspace{4pt}
  \ibox{mint}{}{%
    {\color{mint}\bfseries Python dominates AI/ML:} 31\% of Python
    developers involved in AI work.%
  }
  \vspace{2pt}
  \ibox{rust}{}{%
    {\color{rust}\bfseries C++ surprise:} 11\% of C++ devs report
    AI/ML involvement --- unexpectedly high for a systems language.%
  }
}

\posterbox[navycard, title={Key Takeaways for 2025}
]{name=takeaways, column=2, between=row22 and row24}{
  \fontsize{15}{20}\selectfont
  \begin{enumerate}[itemsep=4pt]
    \item {\color{amber}\bfseries TypeScript} (Promise Index 199) is the clearest momentum signal.
    \item {\color{mint}\bfseries Python} is closing in on JavaScript --- gap may be $<$3 pts by 2025.
    \item {\color{postgres}\bfseries PostgreSQL} is the rising database leader; open-source dominates.
    \item {\color{aws}\bfseries AWS} leads cloud but faces steady erosion from Azure \& GCP.
    \item {\color{accent}\bfseries AI integration} at 18\% signals production AI is no longer niche.
  \end{enumerate}
}

\end{tcbposter}
\end{document}

